/**
 * =============================================================================
 * HEALTH CHECK ROUTES
 * =============================================================================
 * Extracted from api-gateway/src/index.ts
 * Provides connector info, gateway health, and aggregated service health.
 * =============================================================================
 */

import { Router, Request, Response } from 'express';
import { ServiceConfig } from '../config/services';
import { ConnectorMeta } from '../middleware/auth';
import { authenticateToken } from '../middleware/auth';
import { query } from '../db';

// The redisService parameter mirrors `import * as redisService from './services/redis'`
// We only require the subset of methods used by these routes.
interface RedisServiceLike {
  getNotificationSettings(key: string): Promise<object | null>;
  getRedisClient(): import('ioredis').default | null;
}

/**
 * Creates an Express Router containing the health-check routes.
 *
 * @param services  – the services record keyed by service name
 * @param redisService – redis service (or compatible object) that exposes `getNotificationSettings`
 */
export function createHealthRoutes(
  services: Record<string, ServiceConfig>,
  redisService: RedisServiceLike,
): Router {
  const router = Router();

  // ---------------------------------------------------------------------------
  // Connector info endpoint for MCP / AI agent connectors
  // ---------------------------------------------------------------------------
  router.get('/api/connector/info', authenticateToken(true), async (req: Request, res: Response) => {
    const meta = (req as any).connectorMeta as ConnectorMeta | undefined;
    if (!meta || req.user?.role !== 'connector') {
      res.status(403).json({ success: false, error: { code: 'FORBIDDEN', message: 'This endpoint is only available for API-key authenticated connectors' } });
      return;
    }

    let connectorConfig: Record<string, unknown> = {};
    try {
      const settingsRaw = await redisService.getNotificationSettings('platform-settings');
      const settings = (settingsRaw || {}) as Record<string, unknown>;
      const integrations = ((settings as any)?.integrations || []) as Array<Record<string, unknown>>;
      const found = integrations.find((i: any) => i.id === meta.connectorId);
      if (found?.config) connectorConfig = found.config as Record<string, unknown>;
    } catch { /* swallow – non-critical */ }

    res.json({
      id: meta.connectorId,
      name: connectorConfig.name || `Connector ${meta.connectorId}`,
      scopes: meta.scopes,
      allowedDocumentTypes: connectorConfig.allowedDocumentTypes || [],
      workflowPolicy: connectorConfig.workflowPolicy || 'enforce',
      rateLimit: meta.rateLimit,
    });
  });

  // ---------------------------------------------------------------------------
  // Gateway health
  // ---------------------------------------------------------------------------
  router.get('/health', (_req: Request, res: Response) => {
    res.json({
      status: 'healthy',
      service: 'api-gateway',
      version: '0.1.0',
      timestamp: new Date().toISOString(),
    });
  });

  // ---------------------------------------------------------------------------
  // Deep readiness check — verifies critical dependencies are reachable.
  //
  // BACKLOG H6: Gateway `/health` was reporting "healthy" even when
  // downstream services were returning 502. That's correct ACA-style
  // semantics (liveness = "the gateway process is running") but operators
  // expected one health endpoint to reflect the platform-as-a-whole state.
  // This endpoint probes the 5 services without which the platform can't
  // serve a single user-facing flow:
  //
  //   - postgres   — every authed read/write
  //   - redis      — sessions, rate limits, settings, audit cache
  //   - auth       — every login + token refresh
  //   - originate  — document CRUD + verify lookup
  //   - anchoring  — chain-first verify path (BACKLOG H6: previously absent
  //                  from the readiness check; verify flows depend on it)
  //
  // Mounted at both `/health/ready` (k8s convention) and `/health/deep`
  // (the name the user-simulated test report referenced).
  // ---------------------------------------------------------------------------
  const deepHealthHandler = async (_req: Request, res: Response): Promise<void> => {
    const CHECK_TIMEOUT = 3000;
    const checks: Record<string, { status: string; latencyMs: number; error?: string; degradedReasons?: unknown }> = {};

    // Helper: run a check with a timeout
    // KS-1101: a check that resolves with an object answered 2xx but reports itself
    // degraded; it is surfaced as `degraded`, never as `up`.
    async function timedCheck(
      name: string,
      fn: () => Promise<void | { degradedReasons?: unknown }>,
    ): Promise<void> {
      const start = Date.now();
      try {
        const result = await Promise.race([
          fn(),
          new Promise<never>((_, reject) =>
            setTimeout(() => reject(new Error('timeout')), CHECK_TIMEOUT),
          ),
        ]);
        checks[name] = result
          ? { status: 'degraded', latencyMs: Date.now() - start, ...(result.degradedReasons !== undefined ? { degradedReasons: result.degradedReasons } : {}) }
          : { status: 'up', latencyMs: Date.now() - start };
      } catch (err: any) {
        checks[name] = {
          status: 'down',
          latencyMs: Date.now() - start,
          error: err?.message || 'Unknown error',
        };
      }
    }

    // Helper: probe a downstream service's /health
    async function probeService(name: string, key: string): Promise<void> {
      await timedCheck(name, async () => {
        const url = services[key]?.url;
        if (!url) throw new Error(`${key} service URL not configured`);
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), CHECK_TIMEOUT);
        try {
          const resp = await fetch(`${url}/health`, { signal: controller.signal });
          if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
          // KS-1101: anchoring (chain), auth and originate (in-memory fallbacks) answer
          // 200 with `status: 'degraded'`. Read the body so that is not reported as up.
          const body = (await resp.json().catch(() => null)) as { status?: unknown; degradedReasons?: unknown } | null;
          if (body && body.status === 'degraded') return { degradedReasons: body.degradedReasons };
        } finally {
          clearTimeout(timeout);
        }
      });
    }

    await Promise.all([
      timedCheck('postgres', async () => { await query('SELECT 1'); }),
      timedCheck('redis', async () => {
        const client = redisService.getRedisClient();
        if (!client) throw new Error('Redis client not initialised');
        await client.ping();
      }),
      probeService('auth', 'auth'),
      probeService('originate', 'originate'),
      probeService('anchoring', 'anchoring'),
    ]);

    const all = Object.values(checks);
    const downCount = all.filter(c => c.status === 'down').length;
    const degradedCount = all.filter(c => c.status === 'degraded').length;
    // KS-1101 (Wednesday's ruling O-SURFACE, 2026-09-17): readiness counts only `down`.
    // /health/ready is this handler and backs the api-gateway compose healthcheck,
    // mcp-server's service_healthy start and the CI boot wait, so a degraded service
    // is surfaced in the body without failing readiness.
    const ready = downCount === 0;

    res.status(ready ? 200 : 503).json({
      ready,
      status: ready && degradedCount === 0 ? 'healthy' : 'degraded',
      checks,
      summary: {
        total: all.length,
        up: all.length - downCount - degradedCount,
        down: downCount,
        degraded: degradedCount,
      },
      timestamp: new Date().toISOString(),
    });
  };
  router.get('/health/ready', deepHealthHandler);
  router.get('/health/deep', deepHealthHandler);

  // ---------------------------------------------------------------------------
  // Aggregated health check across all services
  //
  // Public exposure of this endpoint is opt-in. The response enumerates every
  // internal service (~20) and their up/down state — it's a free reconnaissance
  // map for an attacker (audit F-04). Set ENABLE_PUBLIC_HEALTH_SERVICES=true
  // ONLY for active platform monitoring; never in production-equivalent envs.
  // The basic /health endpoint above remains public for ACA liveness probes.
  // ---------------------------------------------------------------------------
  router.get('/health/services', async (_req: Request, res: Response) => {
    if (process.env.ENABLE_PUBLIC_HEALTH_SERVICES !== 'true') {
      return res.status(404).json({ success: false, error: { code: 'NOT_FOUND', message: 'Not found' } });
    }
    const serviceHealth: Record<string, { status: string; latency?: number; error?: string }> = {};

    await Promise.all(
      Object.entries(services).map(async ([key, service]) => {
        const start = Date.now();
        try {
          const controller = new AbortController();
          const timeout = setTimeout(() => controller.abort(), 5000);

          const response = await fetch(`${service.url}${service.healthPath}`, {
            signal: controller.signal,
          });

          clearTimeout(timeout);

          serviceHealth[key] = {
            status: response.ok ? 'healthy' : 'unhealthy',
            latency: Date.now() - start,
          };
        } catch (error) {
          serviceHealth[key] = {
            status: 'unreachable',
            latency: Date.now() - start,
            error: error instanceof Error ? error.message : 'Unknown error',
          };
        }
      }),
    );

    const allHealthy = Object.values(serviceHealth).every(s => s.status === 'healthy');

    res.status(allHealthy ? 200 : 503).json({
      status: allHealthy ? 'healthy' : 'degraded',
      gateway: 'healthy',
      services: serviceHealth,
      timestamp: new Date().toISOString(),
    });
  });

  return router;
}

/**
 * =============================================================================
 * KS-1101 — the gateway's health aggregates surface a probed service's
 * `status: 'degraded'` body, and readiness is unchanged
 * =============================================================================
 * Anchoring (chain unreachable), auth and originate (in-memory fallbacks) answer
 * HTTP 200 with `status: 'degraded'`. Every aggregate classified a service by
 * `response.ok` alone, so a degraded service read as `up` / `healthy`.
 *
 * Shape O-SURFACE (ruled by Wednesday, 2026-09-17): every aggregate body shows
 * `degraded` for a probed service that answers 2xx with `status: 'degraded'`, and
 * never shows it as up. Readiness is unchanged: `/health/ready` and `/status/simple`
 * keep their 200 / 503 rules, with degraded counted as not-down, because the
 * api-gateway compose healthcheck, mcp-server's start and the CI boot wait depend
 * on them.
 *
 * Real app (the ks1207 / ks1215 pattern): the app exported by index.ts, `../db`
 * mocked, and every service and portal URL pointed at one of three loopback stubs:
 *   up        200 {status: 'healthy'}
 *   degraded  200 {status: 'degraded', degradedReasons: [...]}
 *   down      503 {status: 'unhealthy'}
 * `getRedisClient` answers PING, so the deep check's redis leg is up. The two
 * required dependencies `/system/status` reads from the environment are set per
 * request, so its control reads `operational`.
 * =============================================================================
 */
import { describe, it, expect, beforeAll, afterAll, vi } from 'vitest';
import http from 'http';
import type { AddressInfo } from 'net';

vi.mock('../db', async (orig) => {
  const real = (await orig()) as Record<string, unknown>;
  return { ...real, isDbAvailable: () => true, query: async () => ({ rows: [{ ok: 1 }], rowCount: 1 }) };
});

vi.mock('../services/redis', async (orig) => {
  const real = (await orig()) as Record<string, unknown>;
  // The deep check's redis leg pings this client; nothing else on these routes needs a live Redis.
  return { ...real, getRedisClient: () => ({ ping: async () => 'PONG' }) };
});

const REASONS = ['ks1101: chain unreachable'];
const RAN = new Set<string>();

type Kind = 'up' | 'degraded' | 'down';
function createStub(kind: Kind): http.Server {
  return http.createServer((_req, res) => {
    const [code, body] = kind === 'down'
      ? [503, { status: 'unhealthy' }]
      : kind === 'degraded'
        ? [200, { status: 'degraded', degradedReasons: REASONS }]
        : [200, { status: 'healthy' }];
    res.writeHead(code, { 'content-type': 'application/json' });
    res.end(JSON.stringify(body));
  });
}
async function listen(server: http.Server): Promise<string> {
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', () => resolve()));
  return `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
}
async function closeServer(server: http.Server | undefined): Promise<void> {
  if (!server) return;
  server.closeAllConnections();
  await new Promise<void>((r) => server.close(() => r()));
}

// Every service URL the three aggregates read at import (config/services.ts and
// routes/system-status.ts), plus the gateway's own URL and the three portals.
const URL_VARS = [
  ...['ANALYTICS', 'ANCHORING', 'AUTH', 'BILLING', 'GOVERNANCE', 'KYC', 'M365', 'NFT', 'NOTIFICATION', 'ORIGINATE',
    'PRISM', 'REFERRAL', 'SECURITY', 'STAKING', 'TIMESTAMPING', 'TRANSFER', 'VC_ISSUER', 'WALLET'].map((n) => `${n}_SERVICE_URL`),
  'API_GATEWAY_URL', 'ISSUER_PORTAL_URL', 'VERIFIER_PORTAL_URL', 'ADMIN_PORTAL_URL',
];

async function bootApp(overrides: Record<string, string>): Promise<{ server: http.Server; url: string }> {
  for (const v of URL_VARS) vi.stubEnv(v, overrides[v] ?? stubUrl.up);
  vi.stubEnv('NODE_ENV', 'test');
  vi.stubEnv('GATEWAY_VOUCH_SECRET', '');
  delete process.env.JWT_JWKS_URL;
  vi.resetModules();
  const app = (await import('../index')).default;
  const server = http.createServer(app as http.RequestListener);
  return { server, url: await listen(server) };
}

type Got = { status: number; body: any };
function get(base: string, path: string): Promise<Got> {
  return new Promise((resolve, reject) => {
    const target = new URL(base);
    const req = http.request({ hostname: target.hostname, port: target.port, path, method: 'GET', agent: false }, (res) => {
      const c: Buffer[] = [];
      res.on('data', (d) => c.push(d));
      res.on('end', () => {
        const text = Buffer.concat(c).toString();
        let body: any = text;
        try { body = JSON.parse(text); } catch { /* non-JSON: keep the text */ }
        resolve({ status: res.statusCode ?? 0, body });
      });
    });
    req.setTimeout(30000, () => req.destroy(new Error(`no response from ${path} within 30 s`)));
    req.on('error', reject);
    req.end();
  });
}

/** `/system/status` reads DATABASE_URL and REDIS_URL per request; set them only for that request. */
async function getSystemStatus(base: string, path: string): Promise<Got> {
  vi.stubEnv('DATABASE_URL', 'postgres://ks1101:unused@127.0.0.1:1/ks1101');
  vi.stubEnv('REDIS_URL', 'redis://127.0.0.1:1');
  try {
    return await get(base, path);
  } finally {
    vi.stubEnv('DATABASE_URL', '');
    vi.stubEnv('REDIS_URL', '');
  }
}

/** A service entry from `/system/status`, whose `services` is grouped by category. */
function systemService(body: any, name: string): any {
  return (Object.values(body?.services ?? {}) as any[][]).flat().find((s) => s?.name === name);
}
function checkStatuses(body: any): Record<string, string> {
  return Object.fromEntries(Object.entries(body?.checks ?? {}).map(([k, v]: [string, any]) => [k, v?.status]).sort(([a], [b]) => a.localeCompare(b)));
}

const stubs: Partial<Record<Kind, http.Server>> = {};
const stubUrl: Record<Kind, string> = { up: '', degraded: '', down: '' };
beforeAll(async () => {
  for (const kind of ['up', 'degraded', 'down'] as Kind[]) {
    stubs[kind] = createStub(kind);
    stubUrl[kind] = await listen(stubs[kind]!);
  }
});
afterAll(async () => {
  for (const s of Object.values(stubs)) await closeServer(s);
  vi.unstubAllEnvs();
});

describe('KS-1101 control — every probed service answers 200 healthy', () => {
  let gateway: { server: http.Server; url: string } | undefined;
  beforeAll(async () => { gateway = await bootApp({}); }, 60000);
  afterAll(async () => { await closeServer(gateway?.server); });

  it('control: /health/deep and /health/ready answer 200, ready and healthy, with every check up', async () => {
    RAN.add('control deep');
    const deep = await get(gateway!.url, '/health/deep');
    const ready = await get(gateway!.url, '/health/ready');
    expect([deep.status, deep.body.ready, deep.body.status, checkStatuses(deep.body), ready.status, ready.body.ready])
      .toEqual([200, true, 'healthy', { anchoring: 'up', auth: 'up', originate: 'up', postgres: 'up', redis: 'up' }, 200, true]);
  });

  it('control: /system/status reads operational, /status/simple 200 ok, and the dashboard 200 healthy', async () => {
    RAN.add('control aggregates');
    const status = await getSystemStatus(gateway!.url, '/api/system/status');
    const simple = await get(gateway!.url, '/api/system/status/simple');
    const dash = await get(gateway!.url, '/api/system/health/dashboard');
    expect([status.status, status.body.status, simple.status, simple.body.status, dash.status, dash.body.status])
      .toEqual([200, 'operational', 200, 'ok', 200, 'healthy']);
  });
});

describe('KS-1101 anchoring answers 200 {status: degraded}', () => {
  let gateway: { server: http.Server; url: string } | undefined;
  beforeAll(async () => { gateway = await bootApp({ ANCHORING_SERVICE_URL: stubUrl.degraded }); }, 60000);
  afterAll(async () => { await closeServer(gateway?.server); });

  it('🔴 /health/deep shows anchoring degraded with its reasons, never up, and reads degraded overall', async () => {
    RAN.add('deep degraded');
    const deep = await get(gateway!.url, '/health/deep');
    const anchoring = deep.body.checks?.anchoring ?? {};
    expect({ anchoring: { status: anchoring.status, degradedReasons: anchoring.degradedReasons }, status: deep.body.status, summary: deep.body.summary })
      .toEqual({ anchoring: { status: 'degraded', degradedReasons: REASONS }, status: 'degraded', summary: { total: 5, up: 4, down: 0, degraded: 1 } });
  });

  it('readiness: /health/ready stays 200 and ready while anchoring is degraded', async () => {
    RAN.add('ready stays 200');
    const ready = await get(gateway!.url, '/health/ready');
    expect([ready.status, ready.body.ready]).toEqual([200, true]);
  });

  it('🔴 /system/status and /api/system/status show anchoring degraded, count it, and read degraded overall, still HTTP 200', async () => {
    RAN.add('status degraded');
    const rows: unknown[] = [];
    for (const path of ['/system/status', '/api/system/status']) {
      const s = await getSystemStatus(gateway!.url, path);
      const a = systemService(s.body, 'anchoring') ?? {};
      rows.push([path, s.status, a.status, a.degradedReasons, s.body.summary?.services?.degraded, s.body.summary?.services?.required?.degraded, s.body.status]);
    }
    expect(rows).toEqual([
      ['/system/status', 200, 'degraded', REASONS, 1, 1, 'degraded'],
      ['/api/system/status', 200, 'degraded', REASONS, 1, 1, 'degraded'],
    ]);
  });

  it('readiness: /status/simple stays 200 on both mounts while anchoring is degraded', async () => {
    RAN.add('simple stays 200');
    const a = await get(gateway!.url, '/system/status/simple');
    const b = await get(gateway!.url, '/api/system/status/simple');
    expect([a.status, b.status]).toEqual([200, 200]);
  });

  it('🔴 /status/simple says degraded in its body and lists anchoring as degraded', async () => {
    RAN.add('simple body degraded');
    const s = await get(gateway!.url, '/api/system/status/simple');
    const a = (s.body.services ?? []).find((x: any) => x?.name === 'anchoring') ?? {};
    expect([s.body.status, a.status]).toEqual(['degraded', 'degraded']);
  });

  it('🔴 the dashboard shows anchoring degraded with its reasons, counts it, and reads degraded, still HTTP 200', async () => {
    RAN.add('dashboard degraded');
    const d = await get(gateway!.url, '/api/system/health/dashboard');
    const a = d.body.services?.anchoring ?? {};
    expect([d.status, d.body.status, a.status, a.degradedReasons, d.body.summary?.degraded, d.body.summary?.unhealthy])
      .toEqual([200, 'degraded', 'degraded', REASONS, 1, 0]);
  });
});

